import type { BankQuestion } from "@/lib/bank";

/** Chemistry Basics (General Science): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"sci-chemistry-1","question":"What is the pH of pure water?","options":["0","5","7","14"],"answer":2,"explanation":"Pure water ionises equally into H⁺ and OH⁻ (each 10⁻⁷ mol/L at 25 °C), so it is neutral with pH 7. At higher temperatures the neutral pH falls slightly below 7, but water stays neutral.","difficulty":"easy"},
  {"id":"sci-chemistry-2","question":"Which gas is most abundant in the Earth’s atmosphere?","options":["Oxygen","Carbon dioxide","Nitrogen","Argon"],"answer":2,"explanation":"Dry air is about 78% nitrogen, 21% oxygen and 0.9% argon; carbon dioxide is only about 0.04%. Oxygen is the tempting answer because it is the gas we need, but it is second.","difficulty":"easy"},
  {"id":"sci-chemistry-3","question":"The chemical formula of common salt is:","options":["NaCl","KCl","NaOH","CaCO₃"],"answer":0,"explanation":"Common salt is sodium chloride, NaCl, an ionic compound of Na⁺ and Cl⁻. KCl (potassium chloride) is used as a salt substitute, and NaOH is caustic soda.","difficulty":"easy"},
  {"id":"sci-chemistry-4","question":"What is the chemical name of baking soda?","options":["Sodium carbonate","Sodium bicarbonate","Calcium carbonate","Ammonium carbonate"],"answer":1,"explanation":"Baking soda is sodium bicarbonate (sodium hydrogencarbonate), NaHCO₃. Sodium carbonate is washing soda, and ammonium carbonate is a different leavening agent (baker's ammonia).","difficulty":"moderate"},
  {"id":"sci-chemistry-5","question":"“Laughing gas” is the common name of:","options":["Nitric oxide","Nitrous oxide","Nitrogen dioxide","Ammonia"],"answer":1,"explanation":"Nitrous oxide, N₂O, is laughing gas and is used as a mild anaesthetic. Nitric oxide is NO, and nitrogen dioxide (NO₂) is a brown, toxic gas, so the near-identical names are the trap.","difficulty":"moderate"},
  {"id":"sci-chemistry-6","question":"A solution with pH 3 is:","options":["Neutral","Acidic","Basic","Saline"],"answer":1,"explanation":"pH below 7 is acidic; the lower the pH, the stronger the acid.","difficulty":"moderate"},
  {"id":"sci-chemistry-7","question":"Which gas is commonly used in fire extinguishers?","options":["Oxygen","Carbon dioxide","Nitrogen","Carbon monoxide"],"answer":1,"explanation":"CO₂ is heavier than air and does not support combustion, so it smothers the fire.","difficulty":"hard"},
  {"id":"sci-chemistry-8","question":"The chemical name of quicklime is:","options":["Calcium carbonate","Calcium oxide","Calcium hydroxide","Calcium sulphate"],"answer":1,"explanation":"Quicklime is calcium oxide (CaO); slaked lime is calcium hydroxide.","difficulty":"hard"},
  {"id":"sci-chemistry-9","question":"Washing soda is chemically:","options":["Na₂CO₃·10H₂O","NaHCO₃","Na₂SO₄·10H₂O","CaCO₃"],"answer":0,"explanation":"Washing soda is sodium carbonate decahydrate, Na₂CO₃·10H₂O. NaHCO₃ is baking soda, and Na₂SO₄·10H₂O, which looks similar, is Glauber's salt (a sulphate, not a carbonate).","difficulty":"hard"},
  {"id":"sci-chemistry-10","question":"Plaster of Paris is chemically:","options":["CaSO₄·2H₂O","CaSO₄·½H₂O","CaCO₃","Ca(OH)₂"],"answer":1,"explanation":"Plaster of Paris is calcium sulphate hemihydrate; gypsum is the dihydrate.","difficulty":"very-hard"},
  {"id":"sci-chemistry-11","question":"The pH of normal human blood is approximately:","options":["6.0","7.0","7.4","8.1"],"answer":2,"explanation":"Blood is slightly alkaline, pH about 7.35–7.45, held there by the bicarbonate buffer. 7.0 is the trap of assuming body fluids are neutral; 6.0 is typical of urine and 8.1 of sea water.","difficulty":"very-hard"},
  {"id":"sci-chemistry-12","question":"Bleaching powder is chemically:","options":["CaOCl₂","CaCl₂","Ca(OH)₂","CaCO₃"],"answer":0,"explanation":"Bleaching powder is calcium oxychloride, CaOCl₂, made by passing chlorine over slaked lime.","difficulty":"very-hard"},
  {"id":"sci-chemistry-13","question":"The chemical formula of washing soda is:","options":["NaHCO₃","Na₂CO₃·10H₂O","Na₂B₄O₇·10H₂O","CaOCl₂"],"answer":1,"explanation":"Washing soda is hydrated sodium carbonate; NaHCO₃ is baking soda.","difficulty":"easy","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-14","question":"The gas used in fire extinguishers is:","options":["Oxygen","Nitrogen","Carbon dioxide","Carbon monoxide"],"answer":2,"explanation":"CO₂ is heavier than air and does not support combustion, so it blankets the fire and cuts off oxygen. Carbon monoxide is itself flammable and poisonous, so it would feed the fire.","difficulty":"easy","source":"SSC CHSL · RRB NTPC"},
  {"id":"sci-chemistry-15","question":"Which metal is liquid at room temperature?","options":["Sodium","Mercury","Gallium","Lead"],"answer":1,"explanation":"Mercury is the only metal that is liquid at ordinary room temperature.","difficulty":"moderate","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-16","question":"The pH of pure water at 25 °C is:","options":["0","7","10","14"],"answer":1,"explanation":"Pure water is neutral; below 7 is acidic and above 7 is basic.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"sci-chemistry-17","question":"Which element has the highest electronegativity?","options":["Oxygen","Chlorine","Fluorine","Nitrogen"],"answer":2,"explanation":"Fluorine, top right of the periodic table, is the most electronegative element.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-18","question":"Brass is an alloy of:","options":["Copper and tin","Copper and zinc","Iron and carbon","Lead and tin"],"answer":1,"explanation":"Brass is copper + zinc (yellow, used in fittings and utensils), while bronze is copper + tin. Mixing up these two copper alloys is the classic trap; iron + carbon is steel and lead + tin is solder.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL"},
  {"id":"sci-chemistry-19","question":"Which of these are chemical changes? 1. Rusting of iron 2. Melting of wax 3. Curdling of milk 4. Sublimation of camphor","options":["1 and 3 only","2 and 4 only","1, 2 and 3","All four"],"answer":0,"explanation":"Rusting and curdling form new substances; melting and sublimation only change state.","difficulty":"hard"},
  {"id":"sci-chemistry-20","question":"How many moles are there in 22 g of carbon dioxide?","options":["0.5","1.0","2.0","22"],"answer":0,"explanation":"Molar mass of CO₂ = 12 + 2 × 16 = 44 g/mol, so 22 ÷ 44 = 0.5 mol. 2.0 comes from dividing the wrong way (44 ÷ 22), and 1.0 from treating 22 g as one mole.","difficulty":"hard"},
  {"id":"sci-chemistry-21","question":"Which of these has the highest pH?","options":["Lemon juice","Pure distilled water","Milk of magnesia","Vinegar"],"answer":2,"explanation":"Milk of magnesia (Mg(OH)₂) is basic, pH about 10.5; the others are acidic or neutral.","difficulty":"very-hard"},
  {"id":"sci-chemistry-22","question":"What volume of oxygen at STP is needed to burn 1 mole of methane completely?","options":["11.2 L","22.4 L","44.8 L","67.2 L"],"answer":2,"explanation":"Balance first: CH₄ + 2O₂ → CO₂ + 2H₂O, so 1 mol methane needs 2 mol O₂ = 2 × 22.4 L = 44.8 L at STP. 22.4 L is the trap of using the unbalanced 1 : 1 ratio.","difficulty":"very-hard"},
  {"id":"sci-chemistry-23","question":"How many of these statements are correct? I. Diamond and graphite are allotropes of carbon. II. Graphite conducts electricity. III. Diamond conducts electricity well. IV. Fullerene (C₆₀) is an allotrope of carbon.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Diamond has no free electrons and does not conduct.","difficulty":"very-hard"},
  {"id":"sci-chemistry-24","question":"How many of these statements are correct? I. Noble gases have completely filled outer shells. II. Helium has eight electrons in its outer shell. III. Argon is the most abundant noble gas in the atmosphere.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. Helium has just two electrons, which fill its only shell.","difficulty":"very-hard"},
  {"id":"sci-chemistry-25","question":"What is the pH of a 0.001 M solution of HCl?","options":["1","3","11","0.001"],"answer":1,"explanation":"HCl ionises fully, so [H⁺] = 10⁻³ M and pH = −log(10⁻³) = 3.","difficulty":"very-hard"},
  {"id":"sci-chemistry-26","question":"How many of these statements are correct? I. Isotopes have the same atomic number. II. Isobars have the same mass number. III. Isotopes have identical physical properties.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Isotopes share chemical properties but differ in physical ones such as mass and density.","difficulty":"very-hard"},
  {"id":"sci-chemistry-27","question":"How many molecules are there in 36 g of water?","options":["3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴","1.505 × 10²³"],"answer":2,"explanation":"The molar mass of H₂O is 18 g/mol, so 36 g is 2 mol, i.e. 2 × 6.022 × 10²³ = 1.204 × 10²⁴ molecules.","difficulty":"very-hard"},
  {"id":"sci-chemistry-28","question":"How many grams of calcium carbonate must be heated to obtain 11.2 L of carbon dioxide at STP? (Ca = 40, C = 12, O = 16)","options":["50 g","100 g","25 g","56 g"],"answer":0,"explanation":"CaCO₃ → CaO + CO₂. 11.2 L at STP is 0.5 mol of CO₂, so 0.5 mol of CaCO₃ (molar mass 100 g/mol) = 50 g is needed.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-29","question":"How many of these statements are correct? I. In the electrolysis of water, hydrogen collects at the anode. II. The volume of oxygen produced is twice that of hydrogen. III. Rusting of iron needs both oxygen and water. IV. Galvanisation coats iron with a layer of tin.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. Hydrogen collects at the cathode (negative electrode), and its volume is twice that of oxygen since water is H₂O. Galvanisation coats iron with zinc, not tin.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-30","question":"The chemical symbol of sodium is:","options":["S","So","Na","Sn"],"answer":2,"explanation":"Na comes from the Latin name natrium; S is sulphur and Sn is tin (stannum).","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-31","question":"The gas evolved when zinc reacts with dilute hydrochloric acid is:","options":["Oxygen","Hydrogen","Chlorine","Carbon dioxide"],"answer":1,"explanation":"Zn + 2HCl → ZnCl₂ + H₂; a metal above hydrogen in the reactivity series displaces hydrogen from a dilute acid.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-32","question":"The atomic number of an element is equal to the number of:","options":["Neutrons","Protons","Nucleons","Isotopes"],"answer":1,"explanation":"Atomic number Z = number of protons (= electrons in a neutral atom); the mass number counts protons plus neutrons.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-33","question":"Which of the following is a noble gas?","options":["Nitrogen","Neon","Hydrogen","Oxygen"],"answer":1,"explanation":"Neon belongs to group 18 (He, Ne, Ar, Kr, Xe, Rn), whose completely filled outer shells make them almost unreactive.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-34","question":"The chemical formula of ozone is:","options":["O","O₂","O₃","O₄"],"answer":2,"explanation":"Ozone is a triatomic allotrope of oxygen, O₃, found in the stratosphere where it absorbs ultraviolet light.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-35","question":"Vinegar is a dilute solution of:","options":["Citric acid","Lactic acid","Acetic acid","Formic acid"],"answer":2,"explanation":"Vinegar contains about 5–8% acetic (ethanoic) acid, CH₃COOH, in water.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-36","question":"Aluminium is extracted mainly from which ore?","options":["Haematite","Bauxite","Galena","Cinnabar"],"answer":1,"explanation":"Bauxite (hydrated aluminium oxide) is purified to alumina and then electrolysed; haematite gives iron, galena lead and cinnabar mercury.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-37","question":"The element present in all acids is:","options":["Oxygen","Chlorine","Hydrogen","Sulphur"],"answer":2,"explanation":"An acid releases H⁺ ions in water; HCl, for example, contains no oxygen, so oxygen is not essential to acids.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-38","question":"Dry ice is:","options":["Frozen water without air","Solid carbon dioxide","Solid ammonia","Frozen nitrogen"],"answer":1,"explanation":"Dry ice is solid CO₂, which sublimes directly to gas at −78.5 °C and so leaves no liquid behind.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-39","question":"The number of neutrons in an atom of ²³Na (atomic number 11) is:","options":["11","12","23","34"],"answer":1,"explanation":"Neutrons = mass number − atomic number = 23 − 11 = 12. 11 is the proton (and electron) count, and 23 is the total number of nucleons, not neutrons.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-40","question":"Which of the following is an endothermic change?","options":["Burning of coal","Respiration","Photosynthesis","Neutralisation of an acid by a base"],"answer":2,"explanation":"Photosynthesis absorbs light energy to make glucose; combustion, respiration and neutralisation all release heat.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-41","question":"The gas released when baking soda is heated is:","options":["Hydrogen","Oxygen","Carbon dioxide","Carbon monoxide"],"answer":2,"explanation":"On heating, 2NaHCO₃ → Na₂CO₃ + H₂O + CO₂, and the carbon dioxide makes cakes rise. Carbon monoxide is not formed, because the carbon in the hydrogencarbonate is already fully oxidised.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-42","question":"In the electrolytic refining of copper, the cathode is made of:","options":["A thick block of impure copper","A thin strip of pure copper","A graphite rod","An inert platinum plate"],"answer":1,"explanation":"The impure copper block is the anode, a pure copper strip is the cathode, and copper sulphate solution is the electrolyte; pure copper deposits on the cathode.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-43","question":"The oxidation number of manganese in KMnO₄ is:","options":["+2","+4","+6","+7"],"answer":3,"explanation":"K is +1 and each O is −2, so +1 + x + 4(−2) = 0 and x = +7, the highest state of Mn. +6 is the trap from K₂MnO₄ (manganate), where two K atoms change the sum.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-44","question":"Phenolphthalein turns which colour in a basic solution?","options":["Red","Pink","Blue","Colourless"],"answer":1,"explanation":"Phenolphthalein is colourless in acid and turns pink in base; litmus is the indicator that turns blue in base.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-45","question":"Sulphuric acid, the “king of chemicals”, is manufactured industrially by the:","options":["Haber process","Contact process","Ostwald process","Solvay process"],"answer":1,"explanation":"The contact process oxidises SO₂ to SO₃ over a V₂O₅ catalyst; Haber makes ammonia, Ostwald nitric acid and Solvay sodium carbonate.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-46","question":"The mass of NaOH required to prepare 500 mL of a 0.2 M solution is (Na = 23, O = 16, H = 1):","options":["2 g","4 g","8 g","40 g"],"answer":1,"explanation":"Moles = molarity × volume in litres = 0.2 × 0.5 = 0.1 mol, and mass = 0.1 × 40 = 4 g. 8 g forgets to convert 500 mL to 0.5 L, and 40 g is the mass of one whole mole.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-47","question":"Temporary hardness of water is caused by the presence of:","options":["Chlorides of calcium and magnesium","Sulphates of calcium and magnesium","Bicarbonates of calcium and magnesium","Dissolved sodium chloride (common salt)"],"answer":2,"explanation":"Bicarbonates decompose on boiling and precipitate as carbonates, so this hardness is “temporary”; chlorides and sulphates cause permanent hardness.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-48","question":"How many of these statements are correct? I. At 25 °C, pH + pOH = 14. II. A solution of pH 2 is ten times more acidic than one of pH 3. III. Milk of magnesia is an acidic suspension. IV. The pH of lemon juice is about 2 to 3.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct (the pH scale is logarithmic). III is wrong: milk of magnesia, Mg(OH)₂, is basic and is used as an antacid.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-49","question":"Assertion (A): Aluminium utensils do not corrode easily in air. Reason (R): A thin, tough layer of aluminium oxide forms on the surface and protects the metal underneath.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Although aluminium is a reactive metal, the Al₂O₃ film formed instantly in air is impermeable and self-healing, so corrosion stops at the surface.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-50","question":"Match the common name with the compound: 1. Gypsum 2. Blue vitriol 3. Epsom salt 4. Caustic soda; a. MgSO₄·7H₂O b. NaOH c. CaSO₄·2H₂O d. CuSO₄·5H₂O","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-a, 2-d, 3-c, 4-b"],"answer":0,"explanation":"Gypsum is CaSO₄·2H₂O, blue vitriol CuSO₄·5H₂O, Epsom salt MgSO₄·7H₂O and caustic soda NaOH.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-51","question":"4 g of hydrogen is burnt with 32 g of oxygen (H = 1, O = 16). The mass of water formed is:","options":["18 g","32 g","36 g","72 g"],"answer":2,"explanation":"2H₂ + O₂ → 2H₂O: 4 g H₂ = 2 mol needs exactly 1 mol (32 g) O₂, giving 2 mol of water = 36 g, consistent with conservation of mass.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-52","question":"Which of the following alloys does NOT contain copper?","options":["Brass","Bronze","German silver","Solder"],"answer":3,"explanation":"Solder is an alloy of lead and tin. Brass is Cu + Zn, bronze Cu + Sn and German silver Cu + Zn + Ni.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-53","question":"How many of these statements are correct? I. Rutherford discovered the nucleus through the alpha-particle scattering experiment. II. Chadwick discovered the neutron in 1932. III. The electron was discovered by Goldstein. IV. The K shell can hold a maximum of eight electrons.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong: J. J. Thomson discovered the electron; Goldstein discovered canal rays. IV is wrong: the K shell holds at most 2 electrons (2n² with n = 1); eight is the L shell's maximum.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-54","question":"Arrange in chronological order: 1. Mendeleev’s periodic table 2. Dobereiner’s triads 3. Moseley’s modern periodic law 4. Newlands’ law of octaves","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"Dobereiner’s triads (1829) → Newlands’ octaves (1866) → Mendeleev’s table (1869) → Moseley’s law based on atomic number (1913).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-55","question":"Assertion (A): Noble gases are chemically inert. Reason (R): Noble gases have completely filled outermost shells.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A stable, filled valence shell (2 for He, 8 for the rest) means there is no tendency to gain, lose or share electrons, which is exactly why they are inert.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-56","question":"The number of oxygen atoms in 8 g of oxygen gas is (O = 16, Avogadro’s number = 6.022 × 10²³):","options":["1.505 × 10²³","3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴"],"answer":1,"explanation":"8 g of O₂ = 8/32 = 0.25 mol of molecules = 0.5 mol of atoms = 0.5 × 6.022 × 10²³ = 3.011 × 10²³ atoms; counting molecules instead gives 1.505 × 10²³.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-57","question":"How many of these statements about metals are correct? I. Sodium is stored under kerosene. II. Gold is the most malleable metal. III. Silver is the best conductor of electricity. IV. Tungsten has the lowest melting point among metals.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: tungsten has the highest melting point of all metals (about 3,400 °C), which is why it is used for bulb filaments.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-58","question":"Match the acid with its natural source: 1. Citric acid 2. Lactic acid 3. Oxalic acid 4. Formic acid; a. Ant sting b. Curd c. Lemon d. Tomato","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Lemon → citric acid, curd → lactic acid, tomato (and spinach) → oxalic acid, ant sting → formic acid.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-59","question":"Which of the following reactions is both a displacement and a redox reaction?","options":["NaOH + HCl → NaCl + H₂O","CaCO₃ → CaO + CO₂","Zn + CuSO₄ → ZnSO₄ + Cu","AgNO₃ + NaCl → AgCl + NaNO₃"],"answer":2,"explanation":"Zinc displaces copper and is oxidised (Zn → Zn²⁺) while Cu²⁺ is reduced. Neutralisation and double displacement involve no change in oxidation state, and the decomposition of CaCO₃ is not redox either.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-60", "question": "The chemical symbol of iron is:", "options": ["Ir", "Fe", "In", "I"], "answer": 1, "explanation": "Fe comes from the Latin name ferrum. Ir is iridium, In is indium and I is iodine.", "difficulty": "easy", "source": "SSC GD · RRB Group D"},
  {"id": "sci-chemistry-61", "question": "The chemical name of common table sugar is:", "options": ["Glucose", "Fructose", "Sucrose", "Lactose"], "answer": 2, "explanation": "Table sugar is sucrose (C₁₂H₂₂O₁₁), a disaccharide of glucose and fructose. Lactose is milk sugar.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-chemistry-62", "question": "Which gas burns with a “pop” sound when a burning splinter is brought near it?", "options": ["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"], "answer": 3, "explanation": "Hydrogen burns explosively with a pop. Oxygen relights a glowing splinter, and carbon dioxide puts a flame out.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-chemistry-63", "question": "Which gas is known as “marsh gas”?", "options": ["Methane", "Ethane", "Butane", "Hydrogen"], "answer": 0, "explanation": "Methane (CH₄) is produced when plant matter decays without air in marshes and paddy fields, hence the name.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id":"sci-chemistry-64","question":"Which acid is secreted in the human stomach?","options":["Sulphuric acid","Hydrofluoric acid","Hydrochloric acid","Acetic acid"],"answer":2,"explanation":"Gastric glands secrete dilute hydrochloric acid, which activates pepsin and kills germs in food.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC"},
  {"id": "sci-chemistry-65", "question": "Liquefied petroleum gas (LPG) used for cooking consists mainly of:", "options": ["Methane and ethane", "Butane and propane", "Hydrogen and carbon monoxide", "Ethylene and acetylene"], "answer": 1, "explanation": "LPG is mostly butane and propane; ethyl mercaptan is added to give it a smell for detecting leaks. CNG is mainly methane.", "difficulty": "moderate", "source": "RRB Group D · SSC CHSL"},
  {"id":"sci-chemistry-66","question":"The depletion of the stratospheric ozone layer is caused mainly by:","options":["Carbon dioxide","Methane","Sulphur hexafluoride","Chlorofluorocarbons"],"answer":3,"explanation":"CFCs release chlorine atoms in the stratosphere, and each chlorine atom can destroy thousands of ozone molecules; the Montreal Protocol phases them out. Sulphur hexafluoride is a powerful greenhouse gas but contains no chlorine and does not deplete ozone.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-67", "question": "The lightest metal is:", "options": ["Sodium", "Lithium", "Aluminium", "Magnesium"], "answer": 1, "explanation": "Lithium has a density of about 0.53 g/cm³, the lowest of all metals; it even floats on oil.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-68", "question": "An element has atomic number 17. Its electronic configuration and valency are:", "options": ["2, 8, 7 and 1", "2, 8, 7 and 7", "2, 7, 8 and 1", "2, 8, 6 and 2"], "answer": 0, "explanation": "17 electrons fill as 2, 8, 7. Needing one more electron to complete its octet, the element (chlorine) has valency 1.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-69","question":"Which gas is produced when water is added to calcium carbide?","options":["Phosphine","Ethylene","Acetylene","Ethane"],"answer":2,"explanation":"CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂. Acetylene (ethyne) is used in welding and to ripen fruit artificially. Phosphine comes from calcium phosphide and water, a reaction often confused with this one.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-70", "question": "What percentage of gold does 18-carat gold contain?", "options": ["18%", "82%", "75%", "90%"], "answer": 2, "explanation": "Pure gold is 24 carat, so 18-carat gold = 18/24 = 3/4 = 75% gold; the rest is usually copper or silver.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-71", "question": "The radioisotope commonly used to diagnose and treat disorders of the thyroid gland is:", "options": ["Cobalt-60", "Iodine-131", "Carbon-14", "Uranium-235"], "answer": 1, "explanation": "The thyroid takes up iodine, so radioactive iodine-131 collects there. Cobalt-60 is used in radiotherapy of other cancers and carbon-14 in dating.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-chemistry-72", "question": "A chlorine atom has atomic number 17 and mass number 35. How many electrons does a chloride ion (Cl⁻) have?", "options": ["17", "35", "16", "18"], "answer": 3, "explanation": "The neutral atom has 17 electrons; gaining one gives Cl⁻ 18 electrons. 35 is the number of nucleons, and the 18 neutrons are a separate count.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-73", "question": "Which of the following is NOT a greenhouse gas?", "options": ["Carbon dioxide", "Methane", "Nitrous oxide", "Nitrogen"], "answer": 3, "explanation": "N₂ does not absorb infrared radiation, so it is not a greenhouse gas even though it makes up 78% of the air. CO₂, CH₄ and N₂O all trap heat.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-74", "question": "What is the percentage of nitrogen by mass in urea, CO(NH₂)₂? (C = 12, N = 14, O = 16, H = 1)", "options": ["23.3%", "46.7%", "28.0%", "60.0%"], "answer": 1, "explanation": "Molar mass = 12 + 16 + 2 × (14 + 2) = 60. Nitrogen = 28. Percentage = 28/60 × 100 ≈ 46.7%, which is why urea is a rich nitrogen fertiliser.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-75", "question": "What is the pH of a 0.01 M solution of sodium hydroxide at 25 °C?", "options": ["2", "10", "13", "12"], "answer": 3, "explanation": "NaOH ionises fully, so [OH⁻] = 10⁻² M and pOH = 2. pH = 14 − 2 = 12. The value 2 is the trap of treating the base like an acid.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-76", "question": "A compound contains 40% carbon, 6.67% hydrogen and 53.33% oxygen by mass, and its molar mass is 180 g/mol. Its molecular formula is:", "options": ["CH₂O", "C₂H₄O₂", "C₆H₁₂O₆", "C₃H₆O₃"], "answer": 2, "explanation": "Mole ratio C : H : O = 40/12 : 6.67/1 : 53.33/16 = 3.33 : 6.67 : 3.33 = 1 : 2 : 1, so the empirical formula is CH₂O (mass 30). 180 ÷ 30 = 6, giving C₆H₁₂O₆.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-77","question":"How many of these statements about periodic trends are correct? I. Atomic radius decreases from left to right across a period. II. Ionisation energy generally decreases across a period. III. Metallic character decreases down a group. IV. Electronegativity increases down a group.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Across a period the rising nuclear charge increases ionisation energy (II wrong); down a group atoms grow larger and lose electrons more easily, so metallic character increases (III wrong) and electronegativity decreases (IV wrong).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-78", "question": "Assertion (A): Hydrogen gas is usually not evolved when a metal reacts with nitric acid. Reason (R): Nitric acid is a strong oxidising agent that oxidises the hydrogen produced to water.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "HNO₃ oxidises the H₂ and is itself reduced to oxides of nitrogen. Only magnesium and manganese give hydrogen with very dilute nitric acid. R explains A.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-79", "question": "Assertion (A): Ionic compounds have high melting points. Reason (R): Ionic compounds are formed by the sharing of electrons between atoms.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: strong electrostatic attraction between ions needs much energy to overcome. R is false: ionic bonds form by transfer of electrons; sharing forms covalent bonds.", "difficulty": "very-hard", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-chemistry-80", "question": "Match the element with its use: 1. Tungsten 2. Chlorine 3. Helium 4. Silicon; a. Solar cells b. Filling weather balloons c. Filaments of electric bulbs d. Disinfecting drinking water", "options": ["1-c, 2-d, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-c, 2-b, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a"], "answer": 3, "explanation": "Tungsten’s very high melting point suits bulb filaments, chlorine kills germs in water, light and non-flammable helium fills balloons, and silicon is the semiconductor in solar cells.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-81","question":"Which of the following is NOT an allotrope of carbon?","options":["Fullerene","Lonsdaleite","Diamond","Carborundum"],"answer":3,"explanation":"Carborundum is silicon carbide (SiC), a compound used as an abrasive. Diamond, graphite, graphene, fullerenes and lonsdaleite (hexagonal diamond) are all forms of pure carbon.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id": "sci-chemistry-82", "question": "How many of these statements are correct? I. Oxidation is the loss of electrons. II. In 2Mg + O₂ → 2MgO, magnesium is oxidised. III. A reducing agent is itself reduced in a reaction. IV. In CuO + H₂ → Cu + H₂O, copper oxide is oxidised.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. A reducing agent is itself oxidised, and in the last reaction CuO loses oxygen, so it is reduced while hydrogen is oxidised.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-83", "question": "What volume of carbon dioxide at STP is produced when 3 g of carbon burns completely in oxygen? (C = 12)", "options": ["22.4 L", "11.2 L", "5.6 L", "2.8 L"], "answer": 2, "explanation": "C + O₂ → CO₂. 3 g of carbon = 3/12 = 0.25 mol, which gives 0.25 mol of CO₂ = 0.25 × 22.4 = 5.6 L.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-84", "question": "How many of these statements are correct? I. Alkanes are saturated hydrocarbons with the general formula CₙH₂ₙ₊₂. II. Ethene has a carbon–carbon double bond. III. The molecular formula of benzene is C₆H₆. IV. Ethanol is the alcohol present in alcoholic drinks.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Alkenes such as ethene (C₂H₄) have a C=C double bond, alkynes a triple bond, and methanol, not ethanol, is the poisonous alcohol.", "difficulty": "very-hard", "source": "RRB Group D · SSC CHSL"},
  {"id": "sci-chemistry-85", "question": "Teflon, used to coat non-stick cookware, is chemically:", "options": ["Polymethyl methacrylate", "Polystyrene", "Polytetrafluoroethylene", "Polyvinyl chloride"], "answer": 2, "explanation": "Teflon is PTFE, a polymer of tetrafluoroethylene (CF₂=CF₂); strong C–F bonds make it slippery, heat-resistant and unreactive. Polymethyl methacrylate is Perspex.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"sci-chemistry-86","question":"The different coloured dyes present in a drop of black ink are best separated by:","options":["Sublimation","Filtration","Chromatography","Fractional distillation"],"answer":2,"explanation":"In paper chromatography each dye moves up the paper at its own speed, so the colours separate into bands. Filtration only removes insoluble solids.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC"},
  {"id":"sci-chemistry-87","question":"For iron to rust, it must be exposed to:","options":["Oxygen only","Both oxygen and water","Carbon dioxide and moisture","Water only"],"answer":1,"explanation":"Rust is hydrated iron(III) oxide, Fe₂O₃·xH₂O, and forms only when both air (oxygen) and moisture are present; iron kept in dry air or in boiled, oil-covered water does not rust.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "sci-chemistry-88", "question": "In the Haber process for making ammonia from nitrogen and hydrogen, the catalyst used is:", "options": ["Vanadium pentoxide", "Nickel", "Platinum", "Iron"], "answer": 3, "explanation": "Finely divided iron (with molybdenum or oxide promoters) is used at about 450 °C and 200 atm. Nickel is used to hydrogenate oils and V₂O₅ in the contact process.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-89","question":"The chief ore from which iron is extracted is:","options":["Cinnabar","Chalcopyrite","Bauxite","Haematite"],"answer":3,"explanation":"Haematite (Fe₂O₃) is the main iron ore and is reduced in a blast furnace. Bauxite is the ore of aluminium, chalcopyrite (copper iron sulphide) is mined for copper, and cinnabar is the ore of mercury.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-90", "question": "The process of making soap by heating fats or oils with sodium hydroxide is called:", "options": ["Fermentation", "Saponification", "Hydrogenation", "Esterification"], "answer": 1, "explanation": "Saponification breaks the fat (an ester) into glycerol and the sodium salts of fatty acids, which are soap. Hydrogenation turns oils into vanaspati ghee.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-91","question":"Soap does not lather well in hard water because:","options":["Soap dissolves too quickly in hard water to form lather","Hard water is acidic and destroys the soap molecules","Ca²⁺ and Mg²⁺ ions form an insoluble scum with soap","Hard water contains extra dissolved oxygen"],"answer":2,"explanation":"Ca²⁺ and Mg²⁺ ions react with soap to give insoluble calcium and magnesium salts (scum), wasting soap until all these ions are used up.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-92","question":"The octane number of petrol is a measure of its:","options":["Calorific value per litre","Volatility (boiling range)","Resistance to knocking","Sulphur content"],"answer":2,"explanation":"A higher octane number means the fuel resists premature ignition (knocking); iso-octane is rated 100 and n-heptane 0. The calorific value is the heat given out on burning.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-93", "question": "At constant temperature, 2 L of a gas at 1 atm is compressed to 0.5 L. Its new pressure is:", "options": ["4 atm", "2 atm", "0.25 atm", "1 atm"], "answer": 0, "explanation": "By Boyle’s law P₁V₁ = P₂V₂, so 1 × 2 = P₂ × 0.5 and P₂ = 4 atm. Reducing the volume to a quarter raises the pressure four times.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-94", "question": "A gas occupies 3 L at 27 °C. Keeping the pressure constant, it is heated to 127 °C. Its new volume is:", "options": ["6 L", "3.3 L", "4 L", "14.1 L"], "answer": 2, "explanation": "Charles’s law needs kelvin: 27 °C = 300 K and 127 °C = 400 K, so V₂ = 3 × 400/300 = 4 L. Using Celsius directly (3 × 127/27) gives the trap 14.1 L.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-95", "question": "Natural rubber is heated with sulphur to make it harder and more elastic. This process is called:", "options": ["Vulcanisation", "Galvanisation", "Polymerisation", "Calcination"], "answer": 0, "explanation": "Vulcanisation forms sulphur cross-links between the rubber chains, so the rubber no longer turns sticky in heat or brittle in cold. Galvanisation is coating iron with zinc.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-97","question":"Gypsum is added to cement during its manufacture in order to:","options":["Make it harder and stronger","Give it a grey colour","Make it waterproof","Slow down its setting"],"answer":3,"explanation":"A few per cent of gypsum (CaSO₄·2H₂O) controls the fast reaction of tricalcium aluminate with water, so the cement does not set too quickly to be worked.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-98", "question": "Which of the following molecules contains a triple bond?", "options": ["CO₂", "H₂O", "N₂", "O₂"], "answer": 2, "explanation": "In N₂ the two atoms share three pairs of electrons (N≡N), which makes nitrogen very unreactive. O₂ has a double bond and each C=O in CO₂ is a double bond.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-99", "question": "When ethanol is warmed with alkaline potassium permanganate (or acidified potassium dichromate), it is converted into:", "options": ["Ethanoic acid", "Ethene", "Ethane", "Ethyl ethanoate"], "answer": 0, "explanation": "These are oxidising agents, and ethanol is oxidised to ethanoic (acetic) acid. Heating ethanol with concentrated sulphuric acid instead dehydrates it to ethene.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-100","question":"Synthetic detergents work well even in hard water because:","options":["They are strongly acidic and dissolve the scum","They soften the water by precipitating the ions","They are made from vegetable oils rather than animal fats","Their calcium and magnesium salts are soluble in water"],"answer":3,"explanation":"Detergents are sodium salts of sulphonic acids (or similar), whose calcium and magnesium salts stay dissolved, so no scum forms and lather is not lost.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-101","question":"Ordinary soda-lime glass is made by fusing together:","options":["Sand, lead oxide and potassium carbonate","Limestone, clay and gypsum","Sand, sodium carbonate and limestone","Clay, sand and gypsum"],"answer":2,"explanation":"Silica (sand), soda ash (Na₂CO₃) and limestone (CaCO₃) are melted together. Limestone, clay and gypsum are the raw materials of cement, and sand with lead oxide and potassium carbonate makes lead crystal (flint) glass.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-102", "question": "Galvanised iron sheets are iron coated with a thin layer of:", "options": ["Nickel", "Zinc", "Chromium", "Tin"], "answer": 1, "explanation": "Zinc is more reactive than iron, so even if the coating is scratched, zinc corrodes first and protects the iron (sacrificial protection). Tin plating, used for food cans, protects only while the layer is unbroken.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-103", "question": "How many of these statements about polymers are correct? I. PVC is a polymer of vinyl chloride. II. Bakelite is a thermoplastic. III. Polythene is a thermosetting plastic. IV. Natural rubber is a polymer of isoprene.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and IV are correct. Bakelite is a thermosetting plastic (it sets permanently and cannot be remoulded), while polythene is a thermoplastic that softens on heating.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-chemistry-104", "question": "Match the mixture with the best method to separate it: 1. Common salt and ammonium chloride 2. Gases of liquefied air 3. Cream from milk 4. Kerosene and water; a. Separating funnel b. Centrifugation c. Fractional distillation d. Sublimation", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a"], "answer": 1, "explanation": "Ammonium chloride sublimes and leaves salt behind, liquefied air is separated by fractional distillation, cream is spun out by centrifugation, and immiscible kerosene and water are separated with a separating funnel.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-105", "question": "Assertion (A): Ethanol mixes with water in all proportions. Reason (R): Ethanol molecules form hydrogen bonds with water molecules.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The –OH group of ethanol forms hydrogen bonds with water, so the two mix completely. Long-chain alcohols are much less soluble because their large hydrocarbon part cannot form such bonds, so R explains A.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-106", "question": "A gas occupies 10 L at 27 °C and 1 atm. What volume will it occupy at 127 °C and 2 atm?", "options": ["4.7 L", "26.7 L", "20 L", "6.67 L"], "answer": 3, "explanation": "By the combined gas law V₂ = V₁ × (T₂/T₁) × (P₁/P₂) = 10 × (400/300) × (1/2) = 6.67 L. Heating alone would raise it to 13.3 L, and doubling the pressure halves that.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-107", "question": "What volume of 0.1 M NaOH is needed to neutralise 25 mL of 0.2 M H₂SO₄ completely?", "options": ["100 mL", "25 mL", "50 mL", "200 mL"], "answer": 0, "explanation": "Moles of H₂SO₄ = 0.025 × 0.2 = 0.005; being dibasic it gives 0.01 mol H⁺, needing 0.01 mol NaOH. Volume = 0.01 ÷ 0.1 = 0.1 L = 100 mL. Treating the acid as monobasic gives the trap 50 mL.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-108", "question": "How many of these statements about fuels are correct? I. CNG consists mainly of methane. II. Ethyl mercaptan is added to LPG so that leaks can be smelt. III. Hydrogen has the highest calorific value per unit mass among common fuels. IV. Anthracite has the highest carbon content among the varieties of coal.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. LPG itself is odourless, so a strong-smelling sulphur compound is added; hydrogen gives about 150 kJ/g, far above petrol or methane; and anthracite (about 90% carbon) ranks above bituminous coal, lignite and peat.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "sci-chemistry-109", "question": "Arrange in chronological order: 1. Invention of nylon 2. Discovery of radioactivity by Becquerel 3. Accidental discovery of Teflon 4. Invention of Bakelite", "options": ["2, 4, 3, 1", "2, 4, 1, 3", "4, 2, 1, 3", "2, 1, 4, 3"], "answer": 1, "explanation": "Becquerel discovered radioactivity in 1896, Baekeland made Bakelite in 1907, Carothers invented nylon in 1935, and Plunkett found Teflon by accident in 1938.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id":"sci-chemistry-110","question":"Which of the following does NOT show the Tyndall effect?","options":["Milk diluted with water","Common salt solution","Smoke from a chimney","Fog"],"answer":1,"explanation":"A salt solution is a true solution whose ions are too small to scatter light, so a beam passing through it is invisible. Milk, fog and smoke are colloids whose particles scatter light and make the beam visible.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-111", "question": "Assertion (A): Iron objects rust faster in coastal areas than in dry inland areas. Reason (R): Salt from sea spray dissolves in moisture and makes it a better conductor, speeding up electrochemical corrosion.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Rusting is an electrochemical process; dissolved salt increases the conductivity of the water film on the iron, so corrosion goes faster near the sea. R explains A.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-112", "question": "Match the compound with its use: 1. Silver iodide 2. Silver bromide 3. Potassium nitrate 4. Zinc phosphide; a. Rat poison b. Gunpowder c. Photographic film d. Cloud seeding", "options": ["1-b, 2-c, 3-d, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-c, 2-d, 3-b, 4-a"], "answer": 1, "explanation": "Silver iodide crystals seed clouds for artificial rain, light-sensitive silver bromide coats photographic film, potassium nitrate (saltpetre) is the oxidiser in gunpowder, and zinc phosphide is a rodenticide.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-113", "question": "Chlorine has two isotopes, Cl-35 and Cl-37, and its average atomic mass is 35.5. The percentage of Cl-37 in natural chlorine is:", "options": ["50%", "25%", "75%", "35.5%"], "answer": 1, "explanation": "Let the fraction of Cl-37 be x: 37x + 35(1 − x) = 35.5, so 2x = 0.5 and x = 0.25, i.e. 25% Cl-37 and 75% Cl-35. 75% is the share of the lighter isotope.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-114", "question": "How many of these statements about chemical bonding are correct? I. Sodium chloride is an ionic compound. II. A water molecule is bent, with a bond angle of about 104.5°. III. A methane molecule is tetrahedral. IV. Carbon dioxide is a polar molecule.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: CO₂ is linear (O=C=O), so the two bond dipoles cancel and the molecule is non-polar, although each C=O bond is polar.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-115","question":"Which of these is a physical change?","options":["Burning of paper","Dissolving sugar in water","Rusting of an iron nail","Cooking an egg until it sets"],"answer":1,"explanation":"Dissolved sugar can be recovered by evaporating the water and no new substance forms, so it is a physical change. Burning, rusting and cooking produce new substances.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id":"sci-chemistry-116","question":"Which gas is given off when an acid reacts with a metal carbonate such as marble chips?","options":["Carbon dioxide","Hydrogen","Oxygen","Sulphur dioxide"],"answer":0,"explanation":"Acid + carbonate → salt + water + carbon dioxide, which turns lime water milky. Acids with active metals give hydrogen instead, and sulphur dioxide comes from sulphites, not carbonates.","difficulty":"easy","source":"SSC CHSL · RRB Group D"},
  {"id": "sci-chemistry-117", "question": "Which of the following is an alloy?", "options": ["Copper", "Iron", "Steel", "Aluminium"], "answer": 2, "explanation": "Steel is mainly iron with a small amount of carbon (and often other metals). Copper, iron and aluminium are pure elements.", "difficulty": "easy", "source": "SSC CHSL · RRB Group D"},
  {"id": "sci-chemistry-118", "question": "Sodium hydroxide is commonly known as:", "options": ["Washing soda", "Baking soda", "Slaked lime", "Caustic soda"], "answer": 3, "explanation": "NaOH is caustic soda, used in making soap and paper. Washing soda is Na₂CO₃·10H₂O, baking soda NaHCO₃ and slaked lime Ca(OH)₂.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-119", "question": "Chemically, rust is mainly:", "options": ["Hydrated iron(III) oxide", "Iron sulphide", "Iron carbonate", "Anhydrous iron(II) oxide"], "answer": 0, "explanation": "Rust is a reddish-brown hydrated ferric oxide, Fe₂O₃·xH₂O, formed when iron reacts with oxygen in the presence of water.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-120", "question": "Which non-metal has a shiny (lustrous) appearance?", "options": ["Sulphur", "Iodine", "Phosphorus", "Carbon in the form of charcoal"], "answer": 1, "explanation": "Iodine crystals have a metallic lustre although iodine is a non-metal. Graphite (another exception) conducts electricity, but charcoal is dull.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-121", "question": "Which metal is the best conductor of electricity?", "options": ["Copper", "Gold", "Silver", "Aluminium"], "answer": 2, "explanation": "Silver has the highest electrical conductivity of all metals, followed by copper. Copper is used for wiring because it is far cheaper.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-122", "question": "Bronze is an alloy of:", "options": ["Copper and zinc", "Iron and carbon", "Lead and tin", "Copper and tin"], "answer": 3, "explanation": "Bronze is copper with tin, used since the Bronze Age for tools, statues and bells. Copper with zinc is brass; lead with tin is solder.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-123","question":"Electrolysis of brine (concentrated sodium chloride solution) in the chlor-alkali process produces:","options":["Sodium hydroxide, chlorine and hydrogen","Sodium metal, chlorine and oxygen","Hydrochloric acid and sodium metal","Sodium carbonate, chlorine and hydrogen"],"answer":0,"explanation":"Chlorine forms at the anode, hydrogen at the cathode, and sodium hydroxide remains in solution; hence ‘chlor-alkali’. Sodium metal needs electrolysis of molten NaCl.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-124","question":"Highly reactive metals such as sodium and magnesium are extracted by:","options":["Heating their oxides strongly with carbon (coke)","Electrolysis of their molten chlorides","Heating their sulphides in air","Dissolving them in water"],"answer":1,"explanation":"These metals hold oxygen more strongly than carbon does, so carbon cannot reduce their oxides; electrolytic reduction of the molten compound is used instead.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-125","question":"An oxide that reacts with both acids and bases to form salt and water is called amphoteric. Which of these is amphoteric?","options":["Sodium oxide","Carbon dioxide","Aluminium oxide","Magnesium oxide"],"answer":2,"explanation":"Al₂O₃ (and ZnO) dissolve in both acids and alkalis. Sodium and magnesium oxides are basic; carbon dioxide is acidic.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-126", "question": "Heating ethanol with excess concentrated sulphuric acid at about 170 °C gives ethene. Here the acid acts as a:", "options": ["Reducing agent", "Oxidising agent", "Catalyst for addition", "Dehydrating agent"], "answer": 3, "explanation": "Concentrated H₂SO₄ removes a molecule of water from ethanol (C₂H₅OH → C₂H₄ + H₂O). Its strong affinity for water also explains why it chars sugar.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-127","question":"In the thermite process used to weld railway tracks, molten iron is produced when:","options":["Aluminium reduces iron(III) oxide, releasing intense heat","Carbon reduces iron oxide in a blast furnace beside the rails","Iron is electrolysed from its molten ore on the spot","Copper displaces iron from iron sulphate in solution"],"answer":0,"explanation":"Fe₂O₃ + 2Al → 2Fe + Al₂O₃ releases so much heat that the iron formed is molten and can fill the gap between rails.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-128","question":"Diamond is extremely hard because:","options":["It contains strong metallic bonds between its carbon atoms","Each C atom is covalently bonded to four others in a rigid 3-D network","It contains free, mobile electrons that bind the atoms tightly together","Its carbon atoms are arranged in loosely held flat layers"],"answer":1,"explanation":"The strong tetrahedral covalent network has no weak planes. Graphite's layers, held by weak forces, slide over each other, which makes it soft and slippery.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-129","question":"n-Butane and isobutane both have the formula C₄H₁₀ but different structures. They are called:","options":["Isotopes","Allotropes","Structural isomers","Geometrical isomers"],"answer":2,"explanation":"Structural isomers have the same molecular formula but different arrangements of atoms (straight versus branched chain). Butanes have no C=C bond, so they cannot show geometrical (cis–trans) isomerism; isotopes and isobars refer to atoms, and allotropes to forms of an element.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-130", "question": "What is the percentage of oxygen by mass in water? (H = 1, O = 16)", "options": ["11.1%", "33.3%", "66.7%", "88.9%"], "answer": 3, "explanation": "H₂O has mass 18, of which oxygen is 16: 16/18 × 100 ≈ 88.9%. The 33.3% trap comes from counting atoms (one in three) instead of mass.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "sci-chemistry-131", "question": "How many of these statements about the reactivity of metals are correct? I. Potassium and sodium react vigorously with cold water. II. Gold and platinum do not react with dilute acids. III. Copper displaces silver from silver nitrate solution. IV. Iron displaces zinc from zinc sulphate solution.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "I, II and III are correct. Zinc is more reactive than iron, so iron cannot displace it; zinc's greater reactivity is also why it protects iron in galvanising. IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-132", "question": "Match the metallurgical step with its description. A. Calcination  B. Roasting  C. Smelting  D. Electrolytic refining; 1. Heating a carbonate ore in little or no air to convert it into an oxide  2. Heating a sulphide ore strongly in excess air  3. Reducing a metal oxide with carbon in a furnace  4. Impure metal as anode and pure metal deposited on the cathode", "options": ["A-2, B-1, C-3, D-4", "A-1, B-2, C-4, D-3", "A-1, B-3, C-2, D-4", "A-1, B-2, C-3, D-4"], "answer": 3, "explanation": "Zinc carbonate is calcined and zinc sulphide roasted, both giving ZnO; smelting with carbon reduces the oxide; copper is purified electrolytically.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-133", "question": "Assertion (A): Graphite conducts electricity, but diamond does not. Reason (R): In graphite each carbon atom is bonded to only three others, leaving one electron per atom free to move.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The delocalised electrons in graphite's layers carry current; in diamond all four valence electrons are locked in bonds, so it is an insulator.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-134", "question": "How many of these statements about pH in daily life are correct? I. Tooth enamel starts to dissolve when the pH in the mouth falls below about 5.5. II. Rain with a pH below about 5.6 is called acid rain. III. Taking an antacid raises the pH of the stomach contents. IV. A solution of pH 9 is more acidic than one of pH 5.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. A lower pH means a more acidic solution, so pH 5 is acidic and pH 9 is basic; IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-135", "question": "Arrange these metals in increasing order of reactivity: 1. Zinc  2. Copper  3. Magnesium  4. Iron", "options": ["2-4-1-3", "2-1-4-3", "4-2-1-3", "2-4-3-1"], "answer": 0, "explanation": "In the activity series, copper < iron < zinc < magnesium. So magnesium displaces zinc, zinc displaces iron, and iron displaces copper from their salt solutions.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-136", "question": "Match the functional group with a compound containing it. A. Alcohol (−OH)  B. Aldehyde (−CHO)  C. Ketone (>C=O)  D. Carboxylic acid (−COOH); 1. Ethanoic acid  2. Propanone (acetone)  3. Methanal (formaldehyde)  4. Ethanol", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-1, B-3, C-2, D-4", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "Ethanol is an alcohol, formaldehyde the simplest aldehyde, acetone (nail-polish remover) the simplest common ketone, and ethanoic acid gives vinegar its sourness.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-137", "question": "How many of these statements about a homologous series are correct? I. Successive members differ by a −CH₂− unit. II. Their molecular masses differ by 14 u. III. All members show similar chemical properties. IV. All members have identical physical properties.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct. Physical properties such as boiling point change gradually as the chain grows, so IV is wrong.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-138", "question": "Assertion (A): Many esters have a pleasant, fruity smell and are used in perfumes and flavourings. Reason (R): Esters are formed when a carboxylic acid reacts with an alcohol in the presence of an acid catalyst.", "options": ["Both A and R are true and R is the correct explanation of A", "A is true but R is false", "Both A and R are true but R is not the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "Both statements are true, but the way an ester is made does not explain why it smells fruity; the smell comes from the volatility and structure of the ester molecules.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id": "sci-chemistry-139", "question": "What is the percentage of water of crystallisation by mass in blue vitriol, CuSO₄·5H₂O? (Cu = 63.5, S = 32, O = 16, H = 1)", "options": ["18.0%", "36.1%", "56.4%", "63.9%"], "answer": 1, "explanation": "CuSO₄ = 159.5 and 5H₂O = 90, so the formula mass is 249.5; 90/249.5 × 100 ≈ 36.1%. Heating drives off this water, turning blue crystals white.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC · RRB Group D"},
  {"id":"sci-chemistry-140","question":"Water stored in an unglazed earthen pot (matka) stays cooler than the surrounding air in summer. The main reason is that:","options":["Clay is a poor conductor and simply keeps the outside heat away","Water seeping out evaporates from the surface, taking latent heat","Clay reacts with water in an endothermic reaction that absorbs heat","Air trapped in the pores of the clay is always colder than outside"],"answer":1,"explanation":"Evaporation needs latent heat, which is drawn from the pot and the water, so the water cools below air temperature. Poor conduction alone could only slow heating, never cool the water below the surroundings.","difficulty":"hard","source":"RRB NTPC · SSC CGL"},
  {"id":"sci-chemistry-141","question":"Which of the following will increase the rate of evaporation of water from wet clothes? I. Spreading the clothes out II. A rise in the humidity of the air III. A stronger wind IV. A rise in temperature","options":["I and III only","II and IV only","I, II, III and IV","I, III and IV only"],"answer":3,"explanation":"Larger surface area, wind and higher temperature all speed up evaporation. Higher humidity slows it, because the air already holds more water vapour.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-142","question":"Which of these substances changes directly from solid to vapour on heating, without first melting?","options":["Camphor","Common salt","Sugar","Paraffin wax"],"answer":0,"explanation":"Camphor sublimes, like naphthalene, iodine and ammonium chloride. Salt and wax melt first, and sugar melts and then chars.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-143","question":"The smell of hot, freshly cooked food reaches us from some distance, but we have to go close to cold food to smell it. This is because:","options":["Hot food produces new kinds of smell molecules that cold food cannot","Particles diffuse faster when hot, as they have more kinetic energy","Air is denser near hot food, so the smell travels further","Cold food absorbs the smell back from the air around it"],"answer":1,"explanation":"The rate of diffusion increases with temperature: hotter vapour particles move faster and spread through air more quickly.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-144","question":"Which of the following is an emulsion, that is, a liquid dispersed in another liquid?","options":["Fog","Smoke","Milk","Shaving foam"],"answer":2,"explanation":"Milk is liquid fat dispersed in water. Fog is a liquid in a gas (aerosol), smoke is a solid in a gas, and shaving foam is a gas in a liquid.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-145","question":"In a dairy, cream is separated from milk by:","options":["Filtration","Centrifugation","Fractional distillation","Sublimation"],"answer":1,"explanation":"Spinning the milk rapidly forces the denser liquid outwards and the lighter fat (cream) collects in the centre. The fat droplets are far too small to be held back by a filter.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-146","question":"Pure copper sulphate is obtained from an impure sample by crystallisation rather than by simply evaporating the solution to dryness, because evaporation to dryness:","options":["Leaves soluble impurities in the solid, and heat may decompose the salt","Converts copper sulphate into copper metal and sulphur dioxide","Removes only part of the water of crystallisation, giving bigger crystals","Is always much slower than crystallisation and wastes fuel"],"answer":0,"explanation":"On evaporating to dryness all dissolved impurities stay in the residue and strong heating can drive off water of crystallisation or decompose the salt; in crystallisation the impurities remain in the mother liquor.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-147","question":"Which of these samples contains the largest number of atoms? (H = 1, He = 4, N = 14, O = 16)","options":["1 g of helium","1 g of nitrogen gas","1 g of oxygen gas","1 g of hydrogen gas"],"answer":3,"explanation":"1 g of H₂ is 0.5 mol of molecules, i.e. 1 mol of atoms. Helium gives 0.25 mol of atoms, N₂ about 0.071 mol and O₂ 0.0625 mol of atoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-148","question":"How many atoms in total are present in one mole of sulphuric acid, H₂SO₄? (Avogadro's number = 6.022 × 10²³)","options":["6.022 × 10²³","4.215 × 10²⁴","3.011 × 10²³","2.409 × 10²⁴"],"answer":1,"explanation":"Each H₂SO₄ molecule has 2 + 1 + 4 = 7 atoms, so one mole contains 7 × 6.022 × 10²³ ≈ 4.215 × 10²⁴ atoms. 6.022 × 10²³ counts molecules, not atoms; 2.409 × 10²⁴ counts only the oxygen atoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-149","question":"Equal masses of oxygen gas (O₂) and sulphur dioxide (SO₂) are taken. What is the ratio of the total number of atoms in the oxygen sample to that in the sulphur dioxide sample? (O = 16, S = 32)","options":["2 : 1","1 : 2","4 : 3","2 : 3"],"answer":2,"explanation":"For mass m, O₂ gives m/32 × 2 = m/16 mol of atoms, and SO₂ gives m/64 × 3 = 3m/64 mol of atoms; the ratio is (1/16) : (3/64) = 4 : 3. The 2 : 1 trap is the ratio of molecules.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-150","question":"An element X has atomic number 13. The formulae of its oxide and its chloride are:","options":["XO and XCl₂","X₃O₂ and XCl₃","X₂O₃ and XCl₂","X₂O₃ and XCl₃"],"answer":3,"explanation":"Configuration 2, 8, 3 gives valency 3 (this is aluminium). With oxygen (valency 2) the formula is X₂O₃, and with chlorine (valency 1) it is XCl₃.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-151","question":"An element has the electronic configuration 2, 8, 2. Its position in the modern periodic table is:","options":["Group 2, Period 3","Group 3, Period 2","Group 2, Period 2","Group 12, Period 3"],"answer":0,"explanation":"Three shells means Period 3, and two valence electrons in an s-block element means Group 2 (this is magnesium).","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-152","question":"The neutron, the uncharged particle in the nucleus, was discovered in 1932 by:","options":["J. J. Thomson","Ernest Rutherford","E. Goldstein","James Chadwick"],"answer":3,"explanation":"Chadwick discovered the neutron. Thomson discovered the electron, Goldstein found canal rays (which led to the proton), and Rutherford discovered the nucleus.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-153","question":"Isotopes of an element have almost identical chemical properties because they have the same:","options":["Number and arrangement of electrons","Mass number and relative atomic mass","Number of neutrons in each nucleus","Density and melting point"],"answer":0,"explanation":"Chemical behaviour depends on electrons, and isotopes have the same atomic number and so the same electrons. They differ in neutrons and mass number, which affects physical properties like density.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-154","question":"Match the radioactive isotope with its use: A. Carbon-14 B. Cobalt-60 C. Uranium-235 D. Iodine-131; 1. Fuel in nuclear power reactors 2. Treating goitre and thyroid disorders 3. Finding the age of ancient wood and fossils 4. Radiotherapy for cancer","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":1,"explanation":"Carbon-14 is used in radiocarbon dating, cobalt-60 gives gamma rays for cancer treatment, uranium-235 undergoes fission in reactors and iodine-131 is taken up by the thyroid.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-155","question":"When the equation Fe + H₂O → Fe₃O₄ + H₂ (steam passed over hot iron) is balanced with the smallest whole numbers, the coefficients of Fe, H₂O, Fe₃O₄ and H₂ are:","options":["3, 4, 1, 4","3, 2, 1, 2","3, 4, 1, 2","1, 4, 1, 4"],"answer":0,"explanation":"Three Fe atoms give one Fe₃O₄; its four O atoms need 4 H₂O, whose 8 H atoms form 4 H₂: 3Fe + 4H₂O → Fe₃O₄ + 4H₂.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-156","question":"Which of these is a double displacement reaction in which an insoluble precipitate is formed?","options":["Zn + CuSO₄ → ZnSO₄ + Cu","CaCO₃ → CaO + CO₂","Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl","Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂"],"answer":2,"explanation":"The ions are exchanged and white insoluble barium sulphate precipitates. Na₂CO₃ + HCl is also an exchange reaction but gives a gas, not a precipitate; the others are single displacement and decomposition.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-157","question":"When water is poured onto quicklime, the mixture becomes very hot. This reaction is best described as:","options":["Decomposition and endothermic","Combination and exothermic","Displacement and exothermic","Combination and endothermic"],"answer":1,"explanation":"CaO + H₂O → Ca(OH)₂: two substances combine into one and release a lot of heat, which is why the mixture hisses and gets hot.","difficulty":"hard","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-158","question":"Two or three days after whitewashing, the walls develop a shiny finish. This is because:","options":["Calcium hydroxide absorbs CO₂ from air, forming calcium carbonate","Calcium hydroxide loses water and turns back into quicklime","Calcium hydroxide reacts with oxygen to form calcium peroxide","Water evaporates and leaves shining crystals of calcium hydroxide"],"answer":0,"explanation":"Slaked lime absorbs CO₂ from the air: Ca(OH)₂ + CO₂ → CaCO₃ + H₂O; the calcium carbonate layer gives the shine.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-159","question":"Packets of potato chips are filled with nitrogen gas mainly to:","options":["Absorb moisture from the air and keep the chips crisp","Let nitrogen react with the oil to form a protective layer","Add a mild flavour and aroma to the chips","Keep out oxygen, which would make the fats and oils rancid"],"answer":3,"explanation":"Nitrogen is unreactive and displaces oxygen, preventing the oxidation (rancidity) of fats; it also cushions the chips. It does not react with the oil or absorb water.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-160","question":"In the reaction CuO + H₂ → Cu + H₂O (on heating), the substance that is oxidised and the substance that acts as the oxidising agent are, respectively:","options":["CuO and H₂","Cu and H₂O","H₂ and CuO","H₂ and Cu"],"answer":2,"explanation":"Hydrogen gains oxygen (is oxidised), while copper oxide loses oxygen (is reduced) and so acts as the oxidising agent; H₂ is the reducing agent.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-161","question":"Silver ornaments and utensils gradually turn black when left exposed to air. The black coating is mainly:","options":["Silver oxide","Silver sulphide","Silver nitrate","Silver carbonate"],"answer":1,"explanation":"Silver reacts with traces of sulphur compounds (such as hydrogen sulphide) in the air to form black silver sulphide; silver hardly reacts with oxygen at room temperature.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-162","question":"A curry (turmeric) stain on a white shirt turns reddish-brown when the shirt is washed with soap, and turns yellow again after rinsing with plenty of water. This shows that:","options":["Soap is acidic, and turmeric is an indicator that turns red in acids","Soap is basic, and turmeric is an indicator that turns red in bases","Soap bleaches the turmeric and turns it into a new red dye","Water reacts chemically with turmeric to make it yellow again"],"answer":1,"explanation":"Turmeric is a natural indicator: yellow in neutral or acidic medium and reddish-brown in basic medium. Soap solution is basic; rinsing removes the soap and the colour returns.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-163","question":"An ant bite causes pain and a burning sensation. Rubbing it with a paste of baking soda gives relief because:","options":["Basic baking soda neutralises the formic acid from the ant","Baking soda neutralises the acetic acid injected by the ant","Baking soda, a strong alkali, dissolves the ant's venom","Baking soda, a mild acid, neutralises the alkaline venom"],"answer":0,"explanation":"Ant stings contain methanoic (formic) acid, not acetic acid; sodium hydrogencarbonate is a mild (weak) base that neutralises it.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-164","question":"While diluting concentrated sulphuric acid, we must add the acid slowly to water with stirring, never water to the acid, because:","options":["Water does not mix with the acid at all if it is added the other way round","The reaction then becomes endothermic and the mixture freezes","Adding water to the acid releases large amounts of poisonous hydrogen gas","Mixing is highly exothermic; a little water on much acid boils and splashes"],"answer":3,"explanation":"Dissolving the acid releases a great deal of heat; when water is added to the acid, the small amount of water boils at once and throws out acid. Adding acid to a large volume of water spreads the heat.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-165","question":"Dry hydrogen chloride gas does not change the colour of dry blue litmus paper, but it turns moist blue litmus red. The reason is that:","options":["Dry HCl gas behaves as a base until it touches water","Litmus paper works only when it is wet, whatever the substance","HCl forms H⁺ (H₃O⁺) ions only when dissolved in water","HCl gas reacts with the dye only in the presence of light"],"answer":2,"explanation":"Acidic behaviour comes from H⁺ ions, which HCl forms only on dissolving in water. In the dry state it stays as covalent molecules, so it cannot show acidic properties.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-166","question":"A large mass of natural gas can be filled into a small steel cylinder as CNG, but the same cannot be done with water. The main reason is that:","options":["Gas particles are much smaller than the molecules of water","Gas particles are far apart, so pressure can push them closer","Gas particles lose part of their mass when they are compressed","Gas particles have very strong forces of attraction between them"],"answer":1,"explanation":"In a gas the particles are far apart, so pressure can push them much closer; in a liquid they are already almost touching, so it is nearly incompressible.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-167","question":"Which of these pairs has the same number of electrons?","options":["A sodium atom and a neon atom","A chloride ion and a neon atom","A potassium ion and a sodium ion","A sodium ion and a neon atom"],"answer":3,"explanation":"Na⁺ has 11 − 1 = 10 electrons, the same as neon. A sodium atom has 11, and Cl⁻ and K⁺ each have 18 electrons.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-168","question":"Hydrochloric acid and acetic acid solutions of the same molar concentration are compared. The hydrochloric acid has a much lower pH because:","options":["It ionises almost fully in water, giving far more H⁺ ions","Its molecules contain more hydrogen atoms than acetic acid","It is a gas, so it dissolves in water faster","Acetic acid is really a base that neutralises itself"],"answer":0,"explanation":"HCl is a strong acid that ionises fully; acetic acid is weak and ionises only slightly. The number of H atoms in the formula is irrelevant: CH₃COOH has four H atoms but only one can ionise.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-169","question":"10 mL of a hydrochloric acid solution of pH 2 is diluted with water to 1 litre. The pH of the diluted solution is about:","options":["2, since dilution does not change pH","3","4","0"],"answer":2,"explanation":"Diluting 100 times reduces [H⁺] from 10⁻² M to 10⁻⁴ M, so the pH rises to 4. Each tenfold dilution of a strong acid raises the pH by one unit.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-170","question":"An aqueous solution of which salt will turn red litmus blue?","options":["Ammonium chloride","Sodium chloride","Copper sulphate","Sodium carbonate"],"answer":3,"explanation":"Sodium carbonate is the salt of a strong base (NaOH) and a weak acid (H₂CO₃), so its solution is basic. NaCl is neutral; ammonium chloride and copper sulphate solutions are acidic.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-171","question":"Plaster of Paris must be stored in a moisture-proof container because:","options":["It reacts with moisture and sets into hard gypsum","It absorbs moisture and slowly turns into quicklime","It catches fire when it comes in contact with moist air","Moisture slowly turns it into washing soda crystals"],"answer":0,"explanation":"CaSO₄·½H₂O combines with water to form gypsum, CaSO₄·2H₂O, which is hard; that is why it is used for plasters for fractured bones but spoils in humid storage.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-172","question":"Bleaching powder is added to water in overhead tanks and wells mainly to:","options":["Remove the hardness of water","Kill germs by releasing chlorine","Remove the colour and smell of iron salts","Make the water slightly alkaline for drinking"],"answer":1,"explanation":"Bleaching powder releases chlorine, a strong oxidising agent that kills disease-causing microbes; it is a disinfectant, not a water softener.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-173","question":"Baking powder contains a mild edible acid such as tartaric acid along with baking soda. The acid is added so that:","options":["The bread becomes harder and stays fresh for many more days","It sweetens the cake and gives it a golden colour","It reacts with the soda to give CO₂, leaving no bitter carbonate","It stops carbon dioxide from being released until the cake cools"],"answer":2,"explanation":"Heating baking soda alone gives CO₂ but leaves sodium carbonate, which tastes bitter. With the acid, the CO₂ is released and the bitter carbonate is not left behind.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-174","question":"Which of these metals does NOT release hydrogen gas when added to dilute hydrochloric acid?","options":["Zinc","Iron","Copper","Magnesium"],"answer":2,"explanation":"Copper is below hydrogen in the reactivity series, so it cannot displace hydrogen from dilute acids. Zn, Fe and Mg are above hydrogen.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-175","question":"A clean iron nail is dipped in blue copper sulphate solution for about 20 minutes. What is observed?","options":["A brown coat forms on the nail and the solution turns pale green","A silvery coating forms on the nail and the solution stays blue","The nail dissolves completely and the solution turns colourless","Nothing happens, because iron is less reactive than copper is"],"answer":0,"explanation":"Iron displaces copper: Fe + CuSO₄ → FeSO₄ + Cu. Reddish-brown copper deposits on the nail and pale green iron sulphate replaces the blue copper sulphate.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-176","question":"Which of these reactions will actually take place? I. Copper strip + silver nitrate solution II. Silver strip + copper sulphate solution III. Iron strip + zinc sulphate solution IV. Zinc strip + iron sulphate solution","options":["I and III only","II and IV only","I and IV only","III and IV only"],"answer":2,"explanation":"A metal displaces only a less reactive metal from its salt. Reactivity: Zn > Fe > Cu > Ag, so Cu displaces Ag and Zn displaces Fe, but Ag cannot displace Cu and Fe cannot displace Zn.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-177","question":"Gold, which does not dissolve in any single common acid, dissolves in aqua regia. Aqua regia is a freshly prepared mixture of:","options":["Concentrated nitric acid and concentrated sulphuric acid in the ratio 3 : 1","Concentrated hydrochloric acid and concentrated sulphuric acid in the ratio 1 : 3","Concentrated hydrochloric acid and concentrated nitric acid in the ratio 1 : 3","Concentrated hydrochloric acid and concentrated nitric acid in the ratio 3 : 1"],"answer":3,"explanation":"Aqua regia (‘royal water’) is 3 parts concentrated HCl to 1 part concentrated HNO₃. The reversed 1 : 3 ratio is a common trap.","difficulty":"hard","source":"RRB NTPC · SSC CGL"},
  {"id":"sci-chemistry-178","question":"Solid sodium chloride does not conduct electricity, but molten sodium chloride does. This is because:","options":["Solid NaCl has no ions at all; ions form only when it melts","Its ions are fixed in the solid but free to move in the melt","Molten NaCl contains free electrons that flow as in a metal","Heat itself carries the electric current through the melt"],"answer":1,"explanation":"Ionic solids already contain ions, but they are locked in the crystal; on melting or dissolving the ions become mobile and can carry current.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-179","question":"Which metal would melt if a piece of it were held in the palm of your hand?","options":["Gallium","Sodium","Aluminium","Lead"],"answer":0,"explanation":"Gallium melts at about 30 °C, below body temperature. Sodium melts near 98 °C, lead at about 327 °C and aluminium at about 660 °C.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-180","question":"White phosphorus is stored under water, whereas sodium is stored under kerosene. The reason for storing phosphorus under water is that:","options":["Phosphorus reacts violently with kerosene and explodes","Phosphorus dissolves in kerosene but not in water","Phosphorus catches fire on its own in air at about 30 °C","Phosphorus needs water around it to remain a solid"],"answer":2,"explanation":"White phosphorus ignites spontaneously in air at about 30 °C, so it is kept away from air under water, with which it does not react. Sodium reacts with water, so it is kept under kerosene instead.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-181","question":"Metals of medium reactivity, such as zinc, are usually extracted from their oxides by:","options":["Electrolysis of the molten ore using graphite electrodes","Heating the ore alone in air until it decomposes","Heating the oxide with a reducing agent such as coke","Displacement from its salt solution with copper"],"answer":2,"explanation":"ZnO + C → Zn + CO. Electrolysis is needed for very reactive metals like Na and Al, heating alone works only for metals low in the series like mercury, and copper cannot displace zinc.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-182","question":"Mercury can be obtained from its ore cinnabar (HgS) simply by heating it in air, while sodium cannot be obtained by heating its compounds. The reason is that mercury:","options":["Has a very low melting point and so simply boils off the ore","Is low in reactivity, so its compounds decompose easily on heating","Is a liquid that separates from the ore by gravity alone","Forms an alloy with sulphur that melts and runs off easily"],"answer":1,"explanation":"Cinnabar is roasted to HgO, which on further heating decomposes into mercury. Highly reactive metals form very stable compounds that need electrolysis.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-183","question":"Solder, used for joining electrical wires, is an alloy chosen for its low melting point. It is made of:","options":["Copper and zinc","Copper and tin","Iron and carbon","Lead and tin"],"answer":3,"explanation":"Solder (lead and tin) melts at a lower temperature than either pure metal, so it can be melted to join wires without harming them. Copper–zinc is brass and copper–tin is bronze.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-184","question":"Stainless steel resists rusting because iron in it is alloyed with:","options":["Chromium and nickel","Copper and zinc","Tin and lead","Aluminium and magnesium"],"answer":0,"explanation":"Chromium forms a thin protective oxide layer on stainless steel, and nickel adds to its resistance to corrosion.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-185","question":"Carbon forms millions of compounds, far more than any other element. The two properties mainly responsible are:","options":["High electronegativity and strong metallic character","Catenation (forming long chains and rings) and a valency of four","The ability to form ionic bonds and to lose four electrons easily","Its presence in all living things and its high melting point"],"answer":1,"explanation":"Carbon bonds strongly to itself, forming chains, branches and rings, and its tetravalency lets it bond to many other atoms. Carbon forms covalent, not ionic, compounds.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-186","question":"How many covalent bonds are present in a molecule of propane, C₃H₈?","options":["8","11","10","20"],"answer":2,"explanation":"Propane has 2 C–C bonds and 8 C–H bonds, a total of 10; in general an alkane CₙH₂ₙ₊₂ has 3n + 1 bonds. 8 counts only the C–H bonds, 11 wrongly gives three carbons three C–C links, and 20 is the number of bonding electrons, not bonds.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-187","question":"Which of these hydrocarbons is unsaturated?","options":["C₂H₆","C₃H₈","C₄H₁₀","C₂H₄"],"answer":3,"explanation":"C₂H₄ (ethene) fits CₙH₂ₙ and has a carbon–carbon double bond. The others fit CₙH₂ₙ₊₂ and are saturated alkanes.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-188","question":"The flame of a household gas stove turns yellow and the bottoms of cooking vessels get blackened. This shows that:","options":["The fuel is burning incompletely for lack of air","The gas has become richer in hydrogen, which burns yellow","The burner is supplying too much oxygen to the flame","The fuel is burning completely and giving out more heat"],"answer":0,"explanation":"With too little air, the fuel burns incompletely and unburnt carbon forms soot and a yellow, luminous flame; cleaning the air holes restores the blue flame.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-189","question":"Vegetable oils are converted into vanaspati ghee by adding hydrogen to them in the presence of a catalyst. The catalyst commonly used is:","options":["Iron","Platinum","Vanadium pentoxide","Nickel"],"answer":3,"explanation":"Hydrogenation of unsaturated oils uses finely divided nickel. Iron catalyses the Haber process and vanadium pentoxide the contact process for sulphuric acid.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-190","question":"Pure ethanoic acid is called glacial acetic acid because:","options":["It is found naturally in glaciers and polar ice","It is used to preserve fish and meat packed in ice","It melts at about 17 °C, so it freezes in winter","It is made by fermenting sugar solutions kept ice-cold"],"answer":2,"explanation":"The melting point of pure ethanoic acid is about 290 K, so in cold climates it solidifies into ice-like crystals.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-191","question":"A small piece of sodium is dropped into ethanol. What happens?","options":["Hydrogen gas is evolved and sodium ethoxide is formed","Carbon dioxide is evolved and sodium ethanoate is formed","Oxygen gas is evolved and sodium hydroxide is formed","No reaction takes place, as ethanol is not an acid"],"answer":0,"explanation":"2Na + 2C₂H₅OH → 2C₂H₅ONa + H₂. Ethanol, like water, reacts with sodium to give hydrogen even though it is neutral to litmus.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-192","question":"Which test can tell a sample of ethanol apart from a sample of ethanoic acid?","options":["Adding a small piece of sodium to each","Adding sodium hydrogencarbonate to each","Mixing each with water","Adding a few drops of phenolphthalein to each"],"answer":1,"explanation":"Only ethanoic acid gives brisk effervescence of CO₂ with NaHCO₃. Both liquids give hydrogen with sodium, both mix with water, and phenolphthalein stays colourless in both.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-193","question":"Drinking spurious liquor containing methanol can cause blindness or death because:","options":["Methanol is converted to ethanol in the body, causing extreme drunken intoxication","Methanol freezes the fluid inside the eyeball and makes it opaque","Methanol directly dissolves the lens of the eye on contact","Methanol is oxidised in the liver to methanal, which damages the optic nerve"],"answer":3,"explanation":"The liver oxidises methanol to methanal, which reacts rapidly with cell components and coagulates protoplasm; the optic nerve is especially affected.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-194","question":"An antacid taken for acidity in the stomach commonly contains:","options":["Calcium oxide (quicklime)","Sodium chloride","Magnesium hydroxide","Ammonium chloride"],"answer":2,"explanation":"Milk of magnesia, Mg(OH)₂, is a mild base that neutralises excess stomach acid. Quicklime is too caustic, NaCl is neutral and ammonium chloride is acidic.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-195","question":"Mendeleev left gaps in his periodic table and predicted the properties of an undiscovered element he called eka-aluminium. When it was discovered, it was named:","options":["Germanium","Scandium","Gallium","Indium"],"answer":2,"explanation":"Gallium, found in 1875, matched the predicted eka-aluminium closely; germanium matched his eka-silicon and scandium his eka-boron.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-196","question":"Among the third-period elements sodium, magnesium, aluminium and silicon, which shows the most metallic character?","options":["Silicon","Aluminium","Magnesium","Sodium"],"answer":3,"explanation":"Metallic character (the tendency to lose electrons) decreases from left to right across a period, so sodium is the most metallic and silicon is a metalloid.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-197","question":"The two main raw materials used to make Portland cement are:","options":["Limestone and clay","Sand and soda ash","Gypsum and sand","Bauxite, coke and cryolite"],"answer":0,"explanation":"Limestone and clay are heated strongly to form clinker, which is ground with a little gypsum. Sand and soda ash (with limestone) are raw materials for glass.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-198","question":"A burning pan of cooking oil should never be put out by pouring water on it because:","options":["Water reacts chemically with the hot oil to form an explosive mixture of gases","Water sinks below the oil, flashes into steam and scatters burning oil","Water increases the oxygen supply reaching the fire","Water itself catches fire when it touches very hot oil"],"answer":1,"explanation":"The water sinks below the oil, flashes into steam and spatters the burning oil. Covering the pan with a lid or a damp cloth cuts off the air instead.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-199","question":"Carbon dioxide is effective in putting out fires, especially those of electrical equipment and oil, because it:","options":["Reacts chemically with the burning fuel to form a compound that cannot burn","Is lighter than air and pushes the flames upward and away","Is heavier than air, does not support burning and is non-conducting","Absorbs heat by decomposing into carbon and oxygen in the flame"],"answer":2,"explanation":"Being denser than air, CO₂ settles over the burning material and keeps oxygen away; it leaves no residue and does not conduct electricity.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-200","question":"The yellowing and pitting of the marble of the Taj Mahal (‘marble cancer’) is caused mainly by:","options":["Acid rain formed from SO₂ and nitrogen oxides","Ozone formed in the lower atmosphere by sunlight","Carbon monoxide from vehicles on nearby roads","Excess oxygen given out by the trees in the nearby gardens"],"answer":0,"explanation":"SO₂ and NO₂ dissolve in rain to form sulphuric and nitric acids, which react with the calcium carbonate of marble and corrode it.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-201","question":"People in some regions who drink groundwater for years develop mottled, brownish teeth and stiff, deformed bones. The most likely cause is excess of which substance in the water?","options":["Iodine","Calcium","Chloride","Fluoride"],"answer":3,"explanation":"A little fluoride protects teeth, but excess causes dental and skeletal fluorosis. Excess calcium makes water hard but does not cause these symptoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-202","question":"Match the disease with the pollutant mainly responsible: A. Minamata disease B. Itai-itai disease C. Blue baby syndrome D. Blackfoot disease; 1. Nitrate in drinking water 2. Mercury 3. Arsenic 4. Cadmium","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Minamata (Japan) was caused by mercury in fish, Itai-itai by cadmium, blue baby syndrome by nitrates that reduce the blood's oxygen-carrying capacity, and blackfoot disease by arsenic in well water.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-203","question":"The gas that leaked from a pesticide factory in the Bhopal gas tragedy of December 1984 was:","options":["Phosgene (carbonyl chloride)","Methyl isocyanate","Chlorine","Hydrogen cyanide"],"answer":1,"explanation":"About 40 tonnes of methyl isocyanate (MIC), used in making a carbamate pesticide, escaped from the Union Carbide plant. Phosgene was used to make MIC but was not the gas that leaked.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-204","question":"Rayon is often called artificial silk. Which statement about it is correct?","options":["It is a fully synthetic fibre made only from petroleum products","It is made by silkworms fed on special chemicals","It is a type of nylon","It is made by chemically treating cellulose from wood pulp"],"answer":3,"explanation":"Rayon is a man-made fibre regenerated from natural cellulose, so it is semi-synthetic. Nylon is fully synthetic from petrochemicals.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-205","question":"Which of these materials is biodegradable?","options":["A polythene carry bag","A PVC pipe","A jute sack","A nylon rope"],"answer":2,"explanation":"Jute is a natural plant fibre (cellulose) that microbes can decompose. Polythene, PVC and nylon are synthetic polymers that persist for very long.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-206","question":"Aspirin, chemically acetylsalicylic acid, is mainly used as:","options":["An antibiotic to kill bacteria","A painkiller and fever-reducer","An antacid to neutralise stomach acid","A disinfectant for wounds"],"answer":1,"explanation":"Aspirin is an analgesic and antipyretic; it also reduces blood clotting. It has no antibacterial action and, being an acid, can irritate the stomach rather than relieve acidity.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-207","question":"Which of these compounds is commonly added to sauces, jams and soft drinks as a preservative?","options":["Sodium benzoate","Calcium oxide","Sodium hydroxide","Sodium hydrogencarbonate"],"answer":0,"explanation":"Sodium benzoate stops the growth of moulds and bacteria in acidic foods. Calcium oxide and sodium hydroxide are caustic, and baking soda is a raising agent.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-208","question":"Which of these fuels has the highest calorific value (heat released per kilogram)?","options":["LPG","Petrol","Methane (CNG)","Hydrogen"],"answer":3,"explanation":"Hydrogen gives about 150 kJ/g, roughly three times as much as LPG, CNG or petrol (about 45–55 kJ/g). Storing it safely is the main problem.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-209","question":"Which variety of coal has the highest percentage of carbon and the highest heating value?","options":["Peat","Anthracite","Lignite","Bituminous coal"],"answer":1,"explanation":"Carbon content rises in the order peat < lignite < bituminous < anthracite, as the plant matter is buried longer and deeper.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-210","question":"In the fractional distillation of crude petroleum, which fraction is collected at the top of the column, at the lowest temperature?","options":["Bitumen","Diesel","Petroleum gas","Lubricating oil"],"answer":2,"explanation":"The column is hottest at the bottom; fractions with the lowest boiling points, such as petroleum gas, rise to the top, while bitumen stays at the bottom.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-211","question":"Coke, used as the reducing agent in the extraction of iron, is obtained by:","options":["Heating coal strongly in the absence of air","Burning coal in excess air","Fractional distillation of petroleum residue","Heating wood in a limited supply of air"],"answer":0,"explanation":"Destructive distillation of coal drives off coal gas and coal tar and leaves coke, almost pure carbon. Heating wood in limited air gives charcoal.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-212","question":"A radioactive sample of mass 16 g has a half-life of 5 days. How much of it remains undecayed after 20 days?","options":["4 g","8 g","0 g","1 g"],"answer":3,"explanation":"20 days is 4 half-lives: 16 → 8 → 4 → 2 → 1 g. It never reaches zero by halving; 4 g would be the answer after only 2 half-lives.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-213","question":"Ordinary filament bulbs are filled with argon rather than air because argon:","options":["Glows brightly and adds to the light given out","Is inert, so the hot filament is not oxidised","Conducts electricity and lowers the resistance","Absorbs the ultraviolet rays from the filament"],"answer":1,"explanation":"In air the white-hot tungsten filament would burn (oxidise) quickly; an inert gas like argon prevents this and slows the evaporation of the filament.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-214","question":"Ice floats on water because:","options":["Ice contains trapped air bubbles that make it light enough to float","Ice molecules are smaller than the molecules of liquid water","Hydrogen bonds hold molecules in an open lattice of lower density","Ice has a higher mass than the same volume of liquid water"],"answer":2,"explanation":"In ice each molecule is hydrogen-bonded in a fixed open lattice, so ice occupies more volume than the same mass of liquid water; even bubble-free ice floats.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-215","question":"In many nuclear reactors in India, heavy water (D₂O) is used as:","options":["The fuel that undergoes fission","A moderator that slows down fast neutrons","A shield that absorbs gamma rays","A source of extra neutrons to start the chain reaction"],"answer":1,"explanation":"Fission works best with slow neutrons, and the deuterium in heavy water slows them down while absorbing very few. Uranium is the fuel.","difficulty":"hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-216","question":"Carbon dioxide is bubbled through lime water. The lime water first turns milky, but if bubbling continues for a long time it becomes clear again. This is because:","options":["CaCO₃ reacts with more CO₂ and water to form soluble Ca(HCO₃)₂","The calcium carbonate decomposes back into calcium oxide","The extra carbon dioxide evaporates the water from the solution","The milkiness was due to air bubbles that later escape"],"answer":0,"explanation":"Ca(OH)₂ + CO₂ → CaCO₃↓ (milky); then CaCO₃ + H₂O + CO₂ → Ca(HCO₃)₂, which dissolves. The same reaction causes temporary hardness of water.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-217","question":"What is the molar mass of aluminium sulphate, Al₂(SO₄)₃? (Al = 27, S = 32, O = 16)","options":["315 g/mol","150 g/mol","294 g/mol","342 g/mol"],"answer":3,"explanation":"2 × 27 + 3 × (32 + 4 × 16) = 54 + 288 = 342 g/mol. 315 uses only one Al atom, 150 treats it as Al₂SO₄, and 294 takes S as 16.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-218","question":"3 g of carbon combines completely with 8 g of oxygen to form carbon dioxide. By the law of constant proportions, how much oxygen will combine completely with 9 g of carbon to form carbon dioxide?","options":["16 g","24 g","27 g","8 g"],"answer":1,"explanation":"Carbon and oxygen always combine in the fixed mass ratio 3 : 8 in CO₂, so 9 g of carbon needs 9 × 8/3 = 24 g of oxygen.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-219","question":"10 g of hydrogen and 64 g of oxygen are made to react to form water. What mass of water is formed? (H = 1, O = 16)","options":["74 g","90 g","72 g","64 g"],"answer":2,"explanation":"64 g O₂ is 2 mol and needs 4 mol (8 g) of H₂, so oxygen is limiting; 4 mol of water = 72 g, and 2 g of hydrogen is left over. 74 g wrongly assumes everything reacts.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-220","question":"At STP, 11.2 litres of a gas has a mass of 22 g. The gas could be: (C = 12, N = 14, O = 16, H = 1)","options":["Carbon dioxide","Oxygen","Nitrogen dioxide","Ammonia"],"answer":0,"explanation":"11.2 L at STP is 0.5 mol, so the molar mass is 22/0.5 = 44 g/mol, which matches CO₂. Nitrogen dioxide (46) is close but not equal, and oxygen (32) and ammonia (17) are far off.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-221","question":"Which of the following processes is exothermic?","options":["Photosynthesis","Respiration","Electrolysis of water","Decomposition of calcium carbonate on heating"],"answer":1,"explanation":"Respiration oxidises glucose and releases energy. Photosynthesis absorbs light energy, and electrolysis and thermal decomposition need a supply of energy.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-222","question":"Cobalt oxide is added to molten glass to give it which colour?","options":["Ruby red","Bottle green","Deep blue","Brown"],"answer":2,"explanation":"Cobalt compounds give glass a deep blue colour. Green glass usually comes from iron or chromium oxides and red from gold or copper compounds.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-223","question":"Assertion (A): Copper vessels left in moist air for a long time develop a green coating. Reason (R): Copper slowly reacts with moist carbon dioxide in the air to form basic copper carbonate.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The green layer is basic copper carbonate, CuCO₃·Cu(OH)₂, formed from moist CO₂ and oxygen; it is the corrosion of copper, just as rust is the corrosion of iron.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-224","question":"Assertion (A): Ionic compounds generally dissolve readily in kerosene and petrol. Reason (R): Ionic compounds are made up of positive and negative ions.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Ionic compounds are made of ions (R is true), but they are generally soluble in water and insoluble in non-polar solvents like kerosene and petrol, so A is false.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-225","question":"Assertion (A): A galvanised iron bucket does not rust even when its zinc coating gets scratched. Reason (R): Zinc is more reactive than iron, so it corrodes in preference to the exposed iron.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Zinc acts as a sacrificial metal: being more reactive, it is oxidised first, protecting the iron even where the iron is exposed. Paint or tin coatings do not protect once broken.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-226","question":"Assertion (A): An aqueous solution of glucose conducts electricity just as dilute hydrochloric acid does. Reason (R): Both glucose and hydrochloric acid contain hydrogen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R is true, but A is false: HCl ionises in water and its solution conducts, while glucose does not ionise at all, so its solution does not conduct. Containing hydrogen does not make a compound produce ions.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-227","question":"How many of these statements are correct? I. Evaporation takes place only at the surface, while boiling takes place throughout the liquid. II. Evaporation can occur at any temperature below the boiling point. III. Water boils at a lower temperature on a high mountain than at sea level. IV. Dissolving common salt in water lowers its boiling point.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; lower air pressure at altitude lowers the boiling point. A dissolved solute such as salt raises the boiling point, so IV is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-228","question":"How many of these statements are correct? I. All bases are alkalis. II. All alkalis are bases. III. Acids turn blue litmus red. IV. Metal oxides are generally basic in nature.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Alkalis are only those bases that dissolve in water, so every alkali is a base but not every base (e.g. Cu(OH)₂) is an alkali. Statements II, III and IV are correct.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-229","question":"Most non-metal oxides are acidic. Which of these non-metal oxides is neutral?","options":["Carbon dioxide","Carbon monoxide","Sulphur dioxide","Phosphorus pentoxide"],"answer":1,"explanation":"CO, like N₂O and H₂O, is a neutral oxide. CO₂, SO₂ and P₂O₅ dissolve in water to form acids.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-230","question":"When magnesium chloride (MgCl₂) is formed from its elements, each magnesium atom:","options":["Gains two electrons, one from each chlorine atom","Shares one pair of electrons with each chlorine atom","Loses one electron to each of two chlorine atoms","Loses two electrons to a single chlorine atom"],"answer":2,"explanation":"Mg (2, 8, 2) gives one electron to each of two Cl atoms, forming Mg²⁺ and two Cl⁻ ions. A chlorine atom needs only one electron to complete its octet, so it cannot take two.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-231","question":"To electroplate a steel spoon with silver, the correct arrangement is:","options":["Spoon as the anode, silver plate as the cathode, copper sulphate solution as electrolyte","Spoon as the cathode, silver plate as the anode, a silver salt solution as electrolyte","Spoon as the cathode, carbon rod as the anode, sodium chloride solution as electrolyte","Spoon and silver plate both as cathodes, dilute sulphuric acid as electrolyte"],"answer":1,"explanation":"Metal ions are deposited at the cathode, so the object to be plated is the cathode; the silver anode dissolves to replace the Ag⁺ ions removed from the silver salt electrolyte.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-232","question":"In the electrolysis of water, a few drops of dilute sulphuric acid are added to the water. This is done because:","options":["Pure water conducts poorly; the acid supplies ions so current flows","The acid supplies the hydrogen gas that collects at the cathode","The acid prevents oxygen from forming at the anode during electrolysis","The acid lowers the boiling point so the water does not overheat"],"answer":0,"explanation":"Pure water has very few ions; adding acid makes it conduct, while the gases collected still come from water in a 2 : 1 volume ratio of hydrogen to oxygen.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-233","question":"Which statement best describes what happens when a candle burns?","options":["Only a physical change occurs, since the wax simply melts","Only a chemical change occurs, since the wax simply burns","Both: wax melts and vaporises, and the wax vapour burns","Neither, since the total mass of wax and products stays the same"],"answer":2,"explanation":"Wax melts and vaporises (physical changes, reversible), and the vapour burns to form CO₂ and water with heat and light (a chemical change). Mass is conserved overall, but the wax itself is used up.","difficulty":"hard","source":"RRB Group D · SSC CHSL"},
  {"id":"sci-chemistry-234","question":"The IUPAC name of the compound CH₃CH₂CHO is:","options":["Propanone","Propanol","Ethanal","Propanal"],"answer":3,"explanation":"Three carbon atoms (prop-) with an aldehyde group (–CHO, suffix -al) give propanal. Propanone is the three-carbon ketone CH₃COCH₃, and ethanal has only two carbons.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-235","question":"Orange-brown bromine water loses its colour when shaken with which of these gases?","options":["Ethene","Methane","Ethane","Carbon dioxide"],"answer":0,"explanation":"Ethene has a C=C double bond and undergoes an addition reaction with bromine, which decolourises it; saturated alkanes like methane and ethane do not react this way in the dark.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-236","question":"In sunlight, methane reacts with chlorine to give chloromethane (CH₃Cl) and hydrogen chloride. This is an example of:","options":["An addition reaction","A substitution reaction","A combustion reaction","A polymerisation reaction"],"answer":1,"explanation":"A hydrogen atom of methane is replaced by a chlorine atom, which is substitution. Saturated hydrocarbons cannot undergo addition since they have no double bond.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-237","question":"How many electrons are shared between the two atoms in an oxygen molecule, O₂?","options":["2","6","8","4"],"answer":3,"explanation":"Each oxygen atom (6 valence electrons) needs two more, so the atoms share two pairs, i.e. 4 electrons, forming a double bond. Six electrons are shared in the triple bond of N₂.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-238","question":"The element with atomic number 16 has a valency of:","options":["6","2","4","8"],"answer":1,"explanation":"Sulphur is 2, 8, 6; it needs two more electrons to complete its octet, so its valency is 8 − 6 = 2. The trap 6 is the number of valence electrons.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-239","question":"Which pair of atomic numbers represents two elements in the same period of the periodic table?","options":["3 and 11","9 and 17","11 and 17","12 and 20"],"answer":2,"explanation":"Elements 11 (Na) and 17 (Cl) both have three shells, so both are in Period 3. The pairs 3 and 11, 9 and 17, and 12 and 20 are in the same groups, not the same periods.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-240","question":"Newlands' law of octaves was found to apply well only to the lighter elements, up to:","options":["Calcium","Sodium","Iron","Uranium"],"answer":0,"explanation":"Newlands' pattern (every eighth element similar) worked only up to calcium; beyond that, elements with very different properties fell into the same column.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-241","question":"When a bottle of soda water is opened, bubbles rush out. The main reason is that:","options":["Air rushing into the bottle displaces dissolved CO₂ from water","Escaping gas cools the soda, and colder water holds less CO₂","Oxygen from the air reacts with carbonic acid to free its CO₂","Pressure above the liquid falls, so less CO₂ stays dissolved"],"answer":3,"explanation":"CO₂ is dissolved under high pressure, and the solubility of a gas falls when the pressure above it drops, so the excess escapes as bubbles. Colder water actually holds more CO₂, and air neither displaces nor reacts with it.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-242","question":"Fish in a pond often come to the surface gasping on very hot summer afternoons. From the chemistry of solutions, the reason is that:","options":["Dissolved oxygen reacts with the hot water and is used up","Gases are less soluble in warmer water, so it holds less oxygen","Hot water dissolves more carbon dioxide, which drives out the nitrogen","Sunlight splits the dissolved oxygen into separate atoms"],"answer":1,"explanation":"Unlike most solids, gases become less soluble in water as the temperature rises, so warm water contains less dissolved oxygen.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-243","question":"The solubility of a salt is 110 g per 100 g of water at 60 °C and 32 g per 100 g of water at 20 °C. If 210 g of its saturated solution at 60 °C is cooled to 20 °C, what mass of salt crystallises out?","options":["78 g","110 g","32 g","142 g"],"answer":0,"explanation":"210 g of saturated solution = 100 g water + 110 g salt. At 20 °C that water can hold only 32 g, so 110 − 32 = 78 g crystallises.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-244","question":"20 g of common salt is dissolved in 80 g of water. The concentration of the solution, by mass percentage, is:","options":["25%","16%","20%","80%"],"answer":2,"explanation":"Mass percentage = mass of solute / mass of solution × 100 = 20/(20 + 80) × 100 = 20%. The trap 25% divides by the mass of the solvent instead of the solution.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-245","question":"A colourless solution turns phenolphthalein pink. What colour will it give with methyl orange?","options":["Red","Pink","Colourless","Yellow"],"answer":3,"explanation":"A pink colour with phenolphthalein shows the solution is basic; methyl orange is yellow in basic solution and red in acidic solution.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-246","question":"When calcium is put into water, it reacts and soon starts floating. The reason is that:","options":["Calcium is a light metal, less dense than water","The calcium hydroxide formed is lighter than water","Hydrogen bubbles cling to the metal and lift it","The heat of the reaction turns the calcium into vapour"],"answer":2,"explanation":"Calcium is actually denser than water; the hydrogen bubbles formed on its surface make it float. The reaction is less vigorous than that of sodium, so the hydrogen does not catch fire.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-247","question":"Gold used in jewellery is usually mixed with a little copper or silver because pure gold is:","options":["Too soft to keep its shape and design","Too reactive and tarnishes quickly","Too brittle and cracks when hammered","Too poor a conductor of heat and electricity"],"answer":0,"explanation":"Pure (24-carat) gold is very soft and malleable; alloying with copper or silver makes it harder. Gold is unreactive and not brittle.","difficulty":"moderate","source":"RRB Group D · SSC MTS"},
  {"id":"sci-chemistry-248","question":"When lead nitrate crystals are heated in a dry test tube, brown fumes are seen. These fumes are of:","options":["Oxygen","Nitrogen dioxide","Bromine vapour","Nitric oxide (NO)"],"answer":1,"explanation":"2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂. Nitrogen dioxide is the brown gas; oxygen and nitric oxide are colourless, and lead oxide is a yellowish solid left behind. Bromine vapour is also brown but contains an element not present in lead nitrate.","difficulty":"hard","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-249","question":"When green ferrous sulphate crystals are heated strongly, they leave a reddish-brown solid and give off gases with the smell of burning sulphur. The gases are:","options":["Hydrogen sulphide and water vapour","Sulphur dioxide and oxygen","Sulphur dioxide and sulphur trioxide","Sulphur trioxide and hydrogen sulphide"],"answer":2,"explanation":"After losing its water of crystallisation, 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃. The reddish-brown solid is ferric oxide.","difficulty":"very-hard","source":"SSC CGL · State PSC"},
  {"id":"sci-chemistry-250","question":"Blue copper sulphate crystals turn white on strong heating and become blue again when a few drops of water are added. The best explanation is that:","options":["The heating decomposes copper sulphate into copper and sulphur","They lose water of crystallisation on heating and regain it later","Heating oxidises the copper, and the added water reduces it again","The blue colour is due to trapped air, which escapes on heating"],"answer":1,"explanation":"CuSO₄·5H₂O loses its five water molecules to become white anhydrous CuSO₄; adding water restores the hydrated blue form. This is why anhydrous copper sulphate is used to test for water.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
  {"id":"sci-chemistry-251","question":"Which statement about ozone is correct?","options":["Stratospheric ozone absorbs UV, but ground-level ozone is a pollutant","Ozone is a molecule made of two oxygen atoms joined by a double bond","The ozone layer lies in the troposphere, close to the Earth's surface","Ozone depletion is caused mainly by rising carbon dioxide levels"],"answer":0,"explanation":"O₃ high up shields life from UV rays, but at ground level it is a toxic component of smog. It has three oxygen atoms, lies in the stratosphere, and is depleted mainly by CFCs.","difficulty":"hard","source":"RRB NTPC · SSC CHSL"},
];

export default questions;
